    float x = 0.0f;
    int index = 0;

    for (int nl = 0; nl < iterations; nl++) {
        // Phase 1: Vectorizable max reduction using 4-wide unroll
        float max0 = a[0], max1 = -FLT_MAX, max2 = -FLT_MAX, max3 = -FLT_MAX;

        int i = 1;
        int limit = LEN_1D - 3;
        for (; i < limit; i += 4) {
            float v0 = a[i+0];
            float v1 = a[i+1];
            float v2 = a[i+2];
            float v3 = a[i+3];
            if (v0 > max0) max0 = v0;
            if (v1 > max1) max1 = v1;
            if (v2 > max2) max2 = v2;
            if (v3 > max3) max3 = v3;
        }
        for (; i < LEN_1D; i++) {
            float v = a[i];
            if (v > max0) max0 = v;
        }
        float max_val = max0;
        if (max1 > max_val) max_val = max1;
        if (max2 > max_val) max_val = max2;
        if (max3 > max_val) max_val = max3;

        // Phase 2: Find index of max_val using 4-wide unroll
        int max_idx = 0;
        int idx0 = 0, idx1 = 0, idx2 = 0, idx3 = 0;

        int j = 0;
        int limit2 = LEN_1D - 3;
        for (; j < limit2; j += 4) {
            if (a[j+0] == max_val) idx0 = j+0;
            if (a[j+1] == max_val) idx1 = j+1;
            if (a[j+2] == max_val) idx2 = j+2;
            if (a[j+3] == max_val) idx3 = j+3;
        }
        for (; j < LEN_1D; j++) {
            if (a[j] == max_val) idx0 = j;
        }
        // Take the last found index (matching scalar semantics)
        max_idx = idx0;
        if (idx1 > max_idx) max_idx = idx1;
        if (idx2 > max_idx) max_idx = idx2;
        if (idx3 > max_idx) max_idx = idx3;

        x = max_val;
        index = max_idx;
    }
    return index + x + 1;
